  `connection_id` bigint DEFAULT NULL COMMENT 'SQL来源数据连接ID',
  `sql_text` longtext COMMENT 'SQL来源查询语句',
  `value_column` varchar(128) DEFAULT NULL COMMENT '值字段列名',
  `label_column` varchar(128) DEFAULT NULL COMMENT '显示字段列名',
