INSERT INTO ai_report_data_business_definition (id,tenant_id,business_code,business_name,business_desc,analysis_goal,metric_definition,dimension_definition,usage_guide,status,create_by,create_time,create_dept,update_by,update_time,del_flag) VALUES
	 (1,1,'user_manage','用户管理','面向日常运营指挥场景，描述业务运行状态、关键过程指标、实时告警、任务处置和资源使用情况，支持管理人员快速判断当前运营健康度。','监控核心业务链路是否稳定，发现流量、订单、服务、告警和任务处理中的异常变化，辅助运营调度和问题定位。','核心指标包括访问量、办理量、完成率、超时率、告警数、待处理数、平均处理时长和资源利用率。实时类指标按最新批次展示，趋势类指标按时间序列展示。','按时间、业务类型、区域、组织、状态、优先级、处理人和渠道等维度分析。','概览区使用汇总数据集；趋势区使用按时间聚合的数据集；告警、任务和事件使用明细数据集生成列表或时间线。',1,1,'2026-05-17 12:26:42',2,1,'2026-06-09 19:42:44',0);
