	 ('39e3765af085a49d57f9541e0d2d7c5a',1,'sample_purchase_order_approval','采购单审批测试流程','用于验证业务模块与流程模块联动：部门负责人、工程部经理、会签、驳回修改、抄送。','purchase','purchase','approval','business','/business/purchase-order-test','{"type":"BUSINESS_CODE_FORM","formMode":"BUSINESS_CODE_FORM","objectCode":"sample_purchase_order","objectName":"采购申请","formKey":"sample_purchase_order_approval_form","formName":"采购单审批表单","providerKey":"samplePurchaseOrder","formUrl":"/business/purchase-order-test","viewKey":"default","formRef":{"type":"BUSINESS_CODE_FORM","objectCode":"sample_purchase_order","providerKey":"samplePurchaseOrder","formKey":"sample_purchase_order_approval_form","formUrl":"/business/purchase-order-test","objectName":"采购申请","formMode":"BUSINESS_CODE_FORM","formName":"采购单审批表单","viewKey":"default"}}',37,'d98f5733-743e-11f1-9216-bec23233f0f6','d9839760-743e-11f1-9216-bec23233f0f6','sample_purchase_order_approval_v37',1,1,'2026-06-30 12:47:52','admin','admin','2026-06-28 15:10:34','2026-06-30 12:47:49',0,'<?xml version="1.0" encoding="UTF-8"?><bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:flowable="http://flowable.org/bpmn" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" id="Definitions_1" targetNamespace="http://flowable.org/bpmn">
  <bpmn:process id="sample_purchase_order_approval" name="采购单审批测试流程" flowable:allowSubmitterWithdraw="true" flowable:autoApprovalMode="none" isExecutable="true">
