    <bpmn:userTask id="dept_leader_approve" name="部门负责人审批" flowable:assignee="${deptLeaderId}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;orderNo&quot;,&quot;fieldCode&quot;:&quot;orderNo&quot;,&quot;label&quot;:&quot;采购单号&quot;,&quot;visible&quot;:false,&quot;editable&quot;:false,&quot;readable&quot;:false,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;title&quot;,&quot;fieldCode&quot;:&quot;title&quot;,&quot;label&quot;:&quot;采购主题&quot;,&quot;visible&quot;:false,&quot;editable&quot;:false,&quot;readable&quot;:false,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;supplierName&quot;,&quot;fieldCode&quot;:&quot;supplierName&quot;,&quot;label&quot;:&quot;供应商&quot;,&quot;visible&quot;:false,&quot;editable&quot;:false,&quot;readable&quot;:false,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;amountCent&quot;,&quot;fieldCode&quot;:&quot;amountCent&quot;,&quot;label&quot;:&quot;采购金额（分）&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;purchaseItems&quot;,&quot;fieldCode&quot;:&quot;purchaseItems&quot;,&quot;label&quot;:&quot;采购明细&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;needDate&quot;,&quot;fieldCode&quot;:&quot;needDate&quot;,&quot;label&quot;:&quot;期望到货日期&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;status&quot;,&quot;fieldCode&quot;:&quot;status&quot;,&quot;label&quot;:&quot;流程状态&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantName&quot;,&quot;fieldCode&quot;:&quot;applicantName&quot;,&quot;label&quot;:&quot;申请人&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantDeptName&quot;,&quot;fieldCode&quot;:&quot;applicantDeptName&quot;,&quot;label&quot;:&quot;申请部门&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderName&quot;,&quot;fieldCode&quot;:&quot;deptLeaderName&quot;,&quot;label&quot;:&quot;部门负责人&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerName&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerName&quot;,&quot;label&quot;:&quot;工程部经理&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignUserNames&quot;,&quot;fieldCode&quot;:&quot;countersignUserNames&quot;,&quot;label&quot;:&quot;会签人员&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;arrivalListFileIds&quot;,&quot;fieldCode&quot;:&quot;arrivalListFileIds&quot;,&quot;label&quot;:&quot;上传清单&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantModifyRemark&quot;,&quot;fieldCode&quot;:&quot;applicantModifyRemark&quot;,&quot;label&quot;:&quot;申请人修改说明&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderRemark&quot;,&quot;fieldCode&quot;:&quot;deptLeaderRemark&quot;,&quot;label&quot;:&quot;部门负责人意见&quot;,&quot;visible&quot;:true,&q