	 ('db5a9b6b38eb9d76f92252a897e56f22',1,'powerstop','停电审核','车间申请停电，分公司审批，动力部审批，调度室制定计划，操作队执行并反馈','3a3f1c1ad95be8cb6a3dc16be414a790','','approval','dynamic',NULL,'[{"key":"outageTime","label":"停电时间","type":"datetime","required":true},{"key":"outageLine","label":"停电线路","type":"input","required":true},{"key":"affectedUnits","label":"涉及单位","type":"textarea","required":false},{"key":"outagePlan","label":"停电计划","type":"textarea","required":false},{"key":"operationResult","label":"操作结果反馈","type":"textarea","required":false}]',3,'powerstop:3:7f622cbd-4e95-11f1-ac6f-5254003c969e','7f5de6fa-4e95-11f1-ac6f-5254003c969e','powerstop_v3',1,1,'2026-05-13 14:32:22','admin','admin','2026-05-12 17:47:39','2026-05-28 15:23:50',0,'<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:flowable="http://flowable.org/bpmn" targetNamespace="http://flowable.org/processdef">
  <bpmn:process id="powerstop" name="停电审核" isExecutable="true" flowable:initiator="initiator">
    <bpmn:startEvent id="StartEvent_1" name="开始" />
