    <bpmn:sequenceFlow id="Flow_008" sourceRef="purchase_countersign" targetRef="Gateway_countersign_result" />
    <bpmn:sequenceFlow id="Flow_009" name="通过" sourceRef="Gateway_countersign_result" targetRef="EndEvent_approved" />
