      <bpmn:conditionExpression xsi:type="bpmn:tFormalExpression"><![CDATA[${approvalResult == ''reject''}]]></bpmn:conditionExpression>
    </bpmn:sequenceFlow>
    <bpmn:sequenceFlow id="Flow_011" sourceRef="applicant_modify" targetRef="Gateway_modify_result" />
