uot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;工程部经理意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignRemark&quot;,&quot;fieldCode&quot;:&quot;countersignRemark&quot;,&quot;label&quot;:&quot;会签意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;rejectReason&quot;,&quot;fieldCode&quot;:&quot;rejectReason&quot;,&quot;label&quot;:&quot;驳回原因&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;remark&quot;,&quot;fieldCode&quot;:&quot;remark&quot;,&quot;label&quot;:&quot;备注&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>
