  <bpmn:process id="sample_purchase_order_approval" name="采购单审批测试流程" flowable:allowSubmitterWithdraw="true" flowable:autoApprovalMode="none" isExecutable="true">
    <bpmn:startEvent id="StartEvent_1" name="提交采购单" flowable:initiator="initiator"/>
    <bpmn:userTask id="dept_leader_approve" name="部门负责人审批" flowable:assignee="${deptLeaderId}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;arrivalListFileIds&quot;,&quot;fieldCode&quot;:&quot;arrivalListFileIds&quot;,&quot;label&quot;:&quot;上传清单&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderRemark&quot;,&quot;fieldCode&quot;:&quot;deptLeaderRemark&quot;,&quot;label&quot;:&quot;部门负责人意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>
