  <bpmn:process id="sample_purchase_order_approval" name="采购单审批测试流程" flowable:allowSubmitterWithdraw="true" flowable:autoApprovalMode="none" isExecutable="true">
    <bpmn:startEvent id="StartEvent_1" name="提交采购单" flowable:initiator="initiator"/>
    <bpmn:userTask id="dept_leader_approve" name="部门负责人审批" flowable:assignee="${deptLeaderId}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;orderNo&quot;,&quot;fieldCode&quot;:&quot;orderNo&quot;,&quot;label&quot;:&quot;采购单号&quot;,&quot;visible&quot;:false,&quot;editable&quot;:false,&quot;readable&quot;:false,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;title&quot;,&quot;fieldCode&quot;:&quot;title&quot;,&quot;label&quot;:&quot;采购主题&quot;,&quot;visible&quot;:false,&quot;editable&quot;:false,&quot;readable&quot;:false,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;supplierName&quot;,&quot;fieldCode&quot;:&quot;supplierName&quot;,&quot;label&quot;:&quot;供应商&quot;,&quot;visible&quot;:false,&quot;editable&quot;:false,&quot;readable&quot;:false,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;amountCent&quot;,&quot;fieldCode&quot;:&quot;amountCent&quot;,&quot;label&quot;:&quot;采购金额（分）&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;purchaseItems&quot;,&quot;fieldCode&quot;:&quot;purchaseItems&quot;,&quot;label&quot;:&quot;采购明细&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;needDate&quot;,&quot;fieldCode&quot;:&quot;needDate&quot;,&quot;label&quot;:&quot;期望到货日期&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;status&quot;,&quot;fieldCode&quot;:&quot;status&quot;,&quot;label&quot;:&quot;流程状态&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantName&quot;,&quot;fieldCode&quot;:&quot;applicantName&quot;,&quot;label&quot;:&quot;申请人&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantDeptName&quot;,&quot;fieldCode&quot;:&quot;applicantDeptName&quot;,&quot;label&quot;:&quot;申请部门&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderName&quot;,&quot;fieldCode&quot;:&quot;deptLeaderName&quot;,&quot;label&quot;:&quot;部门负责人&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerName&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerName&quot;,&quot;label&quot;:&quot;工程部经理&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignUserNames&quot;,&quot;fieldCode&quot;:&quot;countersignUserNames&quot;,&quot;label&quot;:&quot;会签人员&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;arrivalListFileIds&quot;,&quot;fieldCode&quot;:&quot;arrivalListFileIds&quot;,&quot;label&quot;:&quot;上传清单&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantModifyRemark&quot;,&quot;fieldCode&quot;:&quot;applicantModifyRemark&quot;,&quot;label&quot;:&quot;申请人修改说明&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderRemark&quot;,&quot;fieldCode&quot;:&quot;deptLeaderRemark&quot;,&quot;label&quot;:&quot;部门负责人意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;工程部经理意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignRemark&quot;,&quot;fieldCode&quot;:&quot;countersignRemark&quot;,&quot;label&quot;:&quot;会签意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;rejectReason&quot;,&quot;fieldCode&quot;:&quot;rejectReason&quot;,&quot;label&quot;:&quot;驳回原因&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;remark&quot;,&quot;fieldCode&quot;:&quot;remark&quot;,&quot;label&quot;:&quot;备注&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>
    <bpmn:exclusiveGateway id="Gateway_dept_result" name="部门负责人审批结果" default="Flow_003"/>
    <bpmn:userTask id="engineering_manager_approve" name="工程部经理审批" flowable:assignee="${engineeringManagerId}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;工程部经理意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>
    <bpmn:exclusiveGateway id="Gateway_engineering_result" name="工程部经理审批结果" default="Flow_006"/>
    <bpmn:userTask id="purchase_countersign" name="采购会签" flowable:assignee="${assignee}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;countersignRemark&quot;,&quot;fieldCode&quot;:&quot;countersignRemark&quot;,&quot;label&quot;:&quot;会签意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"><bpmn:multiInstanceLoopCharacteristics isSequential="false" flowable:collection="${countersignUserList}" flowable:elementVariable="assignee"><bpmn:completionCondition xsi:type="bpmn:tFormalExpression">${nrOfCompletedInstances/nrOfInstances == 1}</bpmn:completionCondition></bpmn:multiInstanceLoopCharacteristics></bpmn:userTask>
    <bpmn:exclusiveGateway id="Gateway_countersign_result" name="会签审批结果" default="Flow_009"/>
    <bpmn:userTask id="applicant_modify" name="申请人修改" flowable:assignee="${initiator}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;title&quot;,&quot;fieldCode&quot;:&quot;title&quot;,&quot;label&quot;:&quot;采购主题&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:true},{&quot;field&quot;:&quot;supplierName&quot;,&quot;fieldCode&quot;:&quot;supplierName&quot;,&quot;label&quot;:&quot;供应商&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:true},{&quot;field&quot;:&quot;amountCent&quot;,&quot;fieldCode&quot;:&quot;amountCent&quot;,&quot;label&quot;:&quot;采购金额分&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:true},{&quot;field&quot;:&quot;purchaseItems&quot;,&quot;fieldCode&quot;:&quot;purchaseItems&quot;,&quot;label&quot;:&quot;采购明细&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;needDate&quot;,&quot;fieldCode&quot;:&quot;needDate&quot;,&quot;label&quot;:&quot;期望到货日期&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantModifyRemark&quot;,&quot;fieldCode&quot;:&quot;applicantModifyRemark&quot;,&quot;label&quot;:&quot;申请人修改说明&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]" flowable:allowDelegate="false"/>
    <bpmn:exclusiveGateway id="Gateway_modify_result" name="修改处理结果" default="Flow_012"/>
