rue,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;工程部经理意见&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignRemark&quot;,&quot;label&quot;:&quot;会签意见&quot;,&quot;readable&quot;:true,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;rejectReason&quot;,&quot;label&quot;:&quot;驳回原因&quot;,&quot;readable&quot;:true,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;remark&quot;,&quot;label&quot;:&quot;备注&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;createTime&quot;,&quot;label&quot;:&quot;创建时间&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;updateTime&quot;,&quot;label&quot;:&quot;更新时间&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>
    <bpmn:exclusiveGateway id="Gateway_dept_result" name="部门负责人审批结果" default="Flow_003"/>
    <bpmn:userTask id="engineering_manager_approve" name="工程部经理审批" flowable:assignee="${engineeringManagerId}" flowable:formUrl="/business/purchase-order-test" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;engineeringManagerRemark&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>
