      <bpmndi:BPMNShape id="Task_PowerApprove_di" bpmnElement="Task_PowerApprove">
        <dc:Bounds x="600" y="80" width="100" height="80" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="Task_DispatchPlan_di" bpmnElement="Task_DispatchPlan">
        <dc:Bounds x="750" y="80" width="100" height="80" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="Task_Operation_di" bpmnElement="Task_Operation">
        <dc:Bounds x="900" y="80" width="100" height="80" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="ServiceTask_Notify_di" bpmnElement="ServiceTask_Notify">
        <dc:Bounds x="1050" y="80" width="100" height="80" />
