ld&quot;:&quot;countersignUserNames&quot;,&quot;label&quot;:&quot;会签人员&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;arrivalListFileIds&quot;,&quot;label&quot;:&quot;上传清单&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantModifyRemark&quot;,&quot;label&quot;:&quot;申请人修改说明&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderRemark&quot;,&quot;label&quot;:&quot;部门负责人意见&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;工程部经理意见&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignRemark&quot;,&quot;label&quot;:&quot;会签意见&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;rejectReason&quot;,&quot;label&quot;:&quot;驳回原因&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;remark&quot;,&quot;label&quot;:&quot;备注&quot;,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>
