t;fieldCode&quot;:&quot;applicantName&quot;,&quot;label&quot;:&quot;申请人&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantDeptName&quot;,&quot;fieldCode&quot;:&quot;applicantDeptName&quot;,&quot;label&quot;:&quot;申请部门&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderName&quot;,&quot;fieldCode&quot;:&quot;deptLeaderName&quot;,&quot;label&quot;:&quot;部门负责人&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;engineeringManagerName&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerName&quot;,&quot;label&quot;:&quot;工程部经理&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignUserNames&quot;,&quot;fieldCode&quot;:&quot;countersignUserNames&quot;,&quot;label&quot;:&quot;会签人员&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;arrivalListFileIds&quot;,&quot;fieldCode&quot;:&quot;arrivalListFileIds&quot;,&quot;label&quot;:&quot;上传清单&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;applicantModifyRemark&quot;,&quot;fieldCode&quot;:&quot;applicantModifyRemark&quot;,&quot;label&quot;:&quot;申请人修改说明&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;deptLeaderRemark&quot;,&quot;fieldCode&quot;:&quot;deptLeaderRemark&quot;,&quot;label&quot;:&quot;部门负责人意见&quot;,&quot;visible&quot;:true,&q