        <bpmndi:BPMNLabel>
          <dc:Bounds x="707" y="136" width="22" height="14" />
        </bpmndi:BPMNLabel>
      </bpmndi:BPMNShape>
      <bpmndi:BPMNEdge id="flow_start_to_supervisor_di" bpmnElement="flow_start_to_supervisor">
